<?php
/**
 * Super Admin: generate and track gift codes.
 *
 * @var array $codes
 * @var array $organizations
 * @var string[] $newCodes codes generated by the previous request (shown once)
 */

use App\Infrastructure\Security\Csrf;

use function App\Infrastructure\Theme\e;
use function App\Infrastructure\Theme\t;
use function App\Infrastructure\Theme\icon;
use function App\Infrastructure\Theme\badge;

$statusTone = ['active' => 'active', 'redeemed' => 'paid', 'revoked' => 'cancelled'];
?>
<section class="card">
    <h1><?= e(t('wallet_gift.title')) ?></h1>
    <p class="muted"><?= e(t('wallet_gift.subtitle')) ?></p>

    <?php if ($newCodes !== []): ?>
        <div class="alert alert--success">
            <p><strong><?= e(t('wallet_gift.new_codes')) ?></strong></p>
            <pre class="gift-codes ltr"><?= e(implode("\n", $newCodes)) ?></pre>
        </div>
    <?php endif; ?>
</section>

<section class="card card--form">
    <h2><?= e(t('wallet_gift.generate_title')) ?></h2>
    <form method="post" action="/admin/wallet/gift-codes">
        <?= Csrf::field() ?>
        <div class="form-grid">
            <div>
                <label for="amount"><?= e(t('wallet.amount')) ?></label>
                <input type="number" id="amount" name="amount" min="1" step="0.001" required>
            </div>
            <div>
                <label for="count"><?= e(t('wallet_gift.count')) ?></label>
                <input type="number" id="count" name="count" min="1" max="100" value="1" data-no-format>
            </div>
            <div>
                <label for="organization_id"><?= e(t('wallet_gift.for_organization')) ?></label>
                <select id="organization_id" name="organization_id">
                    <option value=""><?= e(t('wallet_gift.any_organization')) ?></option>
                    <?php foreach ($organizations as $org): ?>
                        <option value="<?= e($org['id']) ?>"><?= e($org['name']) ?></option>
                    <?php endforeach; ?>
                </select>
            </div>
            <div>
                <label for="expires_at"><?= e(t('wallet_gift.expires_at')) ?></label>
                <input type="text" class="crm-datepicker" id="expires_at" name="expires_at" value="">
            </div>
        </div>
        <label for="note"><?= e(t('wallet_gift.note')) ?></label>
        <input type="text" id="note" name="note" maxlength="255">
        <button type="submit" class="btn btn--primary"><?= icon('plus') ?><?= e(t('wallet_gift.generate')) ?></button>
    </form>
</section>

<section class="card">
    <h2><?= e(t('wallet_gift.list_title')) ?></h2>
    <div class="table-responsive">
    <table class="table table--compact">
        <thead>
            <tr>
                <th><?= e(t('wallet_gift.code')) ?></th>
                <th><?= e(t('wallet.amount')) ?></th>
                <th><?= e(t('wallet_gift.for_organization')) ?></th>
                <th><?= e(t('wallet_gift.expires_at')) ?></th>
                <th><?= e(t('deals.status')) ?></th>
                <th><?= e(t('wallet_gift.redeemed_by')) ?></th>
                <th><span class="visually-hidden"><?= e(t('contacts.row_actions')) ?></span></th>
            </tr>
        </thead>
        <tbody>
        <?php foreach ($codes as $c): ?>
            <tr>
                <td><code class="ltr"><?= e($c['code']) ?></code><?php if (!empty($c['note'])): ?><div class="muted"><?= e($c['note']) ?></div><?php endif; ?></td>
                <td class="num"><span class="ltr"><?= e(number_format((float) $c['amount'])) ?></span> <?= e($c['currency_code'] ?? '') ?></td>
                <td><?= e($c['organization_name'] ?? t('wallet_gift.any_organization')) ?></td>
                <td class="muted"><span class="ltr"><?= e($c['expires_at'] ?? '—') ?></span></td>
                <td><?= badge(t('wallet_gift.status.' . $c['status']), $statusTone[$c['status']] ?? $c['status']) ?></td>
                <td class="muted">
                    <?php if ($c['status'] === 'redeemed'): ?>
                        <?= e(trim((string) $c['redeemed_by_name'])) ?> — <?= e($c['redeemed_organization_name'] ?? '') ?><br><span class="ltr"><?= e($c['redeemed_at']) ?></span>
                    <?php else: ?>—<?php endif; ?>
                </td>
                <td class="actions-cell">
                    <?php if ($c['status'] === 'active'): ?>
                        <form method="post" action="/admin/wallet/gift-codes/<?= e($c['id']) ?>/revoke" class="inline-form">
                            <?= Csrf::field() ?>
                            <button type="submit" class="btn btn--sm btn--danger" data-confirm="<?= e(t('wallet_gift.revoke_confirm')) ?>"><?= icon('ban') ?><?= e(t('wallet_gift.revoke')) ?></button>
                        </form>
                    <?php endif; ?>
                </td>
            </tr>
        <?php endforeach; ?>
        <?php if ($codes === []): ?>
            <tr><td colspan="7" class="muted"><?= e(t('wallet_gift.empty')) ?></td></tr>
        <?php endif; ?>
        </tbody>
    </table>
    </div>
</section>
